import{_ as a,a0 as p,w as i,s as u,ao as l,I as r,x as n,a1 as o,A as s}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"Linux有問必答：Ubuntu桌面上如何禁用默認的密鑰環解鎖提示 | LCTT x X-CMD","titleTemplate":false,"description":"Linux有問必答：Ubuntu桌面上如何禁用默認的密鑰環解鎖提示 | LCTT (201506) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux有問必答：Ubuntu桌面上如何禁用默認的密鑰環解鎖提示 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux有問必答：Ubuntu桌面上如何禁用默認的密鑰環解鎖提示 | LCTT (201506) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201506/20150506 Linux FAQs with Answers--How to disable entering password for default keyring to unlock on Ubuntu desktop","title":"Linux有問必答：Ubuntu桌面上如何禁用默認的密鑰環解鎖提示","tag":"201506","desc":""},"relativePath":"201506/20150506 Linux FAQs with Answers--How to disable entering password for default keyring to unlock on Ubuntu desktop.md","filePath":"[post].md"}'),d={name:"201506/20150506 Linux FAQs with Answers--How to disable entering password for default keyring to unlock on Ubuntu desktop.md"};function m(f,t,b,k,g,x){const e=p("Link");return i(),u("div",null,[t[13]||(t[13]=l(`<h1 id="linux有問必答-ubuntu桌面上如何禁用默認的密鑰環解鎖提示" tabindex="-1">Linux有問必答：Ubuntu桌面上如何禁用默認的密鑰環解鎖提示 <a class="header-anchor" href="#linux有問必答-ubuntu桌面上如何禁用默認的密鑰環解鎖提示" aria-label="Permalink to “Linux有問必答：Ubuntu桌面上如何禁用默認的密鑰環解鎖提示”">​</a></h1><blockquote><p><strong>問題</strong>：當我啓動我的Ubuntu桌面時，出現了一個彈出對話框，要求我輸入密碼來解鎖默認的密鑰環。我怎樣才能禁用這個“解鎖默認密鑰環”彈出窗口，並自動解鎖我的密鑰環？</p></blockquote><p>密鑰環是一個以加密方式存儲你的登錄信息的本地資料庫。各種桌面應用（如瀏覽器、電子郵件客户端）使用密鑰環來安全地存儲並管理你的登錄憑證、機密、密碼、證書或密鑰。對於那些需要檢索存儲在密鑰環中的信息的應用程序，需要解鎖該密鑰環。</p><p>Ubuntu桌面所使用的GNOME密鑰環被整合到了桌面登錄中，該密鑰環會在你驗證進入桌面後自動解鎖。但是，如果你設置了自動登錄桌面或者是從休眠中喚醒，你默認的密鑰環仍然可能“被鎖定”的。在這種情況下，你會碰到這一提示：</p><blockquote><p>“輸入密碼來解鎖密鑰環‘默認密鑰環’。某個應用想要訪問密鑰環‘默認密鑰環’，但它被鎖定了。”</p></blockquote><p><img src="https://farm9.staticflickr.com/8787/16716456754_309c39513c_o.png" alt=""></p><p>如果你想要避免在每次彈出對話框出現時輸入密碼來解鎖默認密鑰環，那麼你可以這樣做。</p><p>在做之前，請先了解禁用密碼提示後可能出現的結果。通過自動解鎖默認密鑰環，你可以讓任何使用你桌面的人無需知道你的密碼而能獲取你的密鑰環（以及存儲在密鑰環中的任何信息）。</p><h3 id="禁用默認密鑰環解鎖密碼" tabindex="-1">禁用默認密鑰環解鎖密碼 <a class="header-anchor" href="#禁用默認密鑰環解鎖密碼" aria-label="Permalink to “禁用默認密鑰環解鎖密碼”">​</a></h3><p>打開Dash，然後輸入“password”來啓動“密碼和密鑰”應用。</p><p><img src="https://farm8.staticflickr.com/7709/17312949416_ed9c4fbe2d_b.jpg" alt=""></p><p>或者，使用seahorse命令從命令列啓動圖形界面。</p><pre><code>$ seahorse 
</code></pre><p>在左側面板中，右擊“默認密鑰環”，並選擇“修改密碼”。</p><p><img src="https://farm8.staticflickr.com/7740/17159959750_ba5b675b00_b.jpg" alt=""></p><p>輸入你的當前登錄密碼。</p><p><img src="https://farm8.staticflickr.com/7775/17347551135_ce09260818_b.jpg" alt=""></p><p>在設置“默認”密鑰環新密碼的密碼框中留空。</p><p><img src="https://farm8.staticflickr.com/7669/17345663222_c9334c738b_c.jpg" alt=""></p><p>在詢問是否不加密存儲密碼對話框中點擊“繼續”。</p><p><img src="https://farm8.staticflickr.com/7761/17152692309_ce3891a0d9_c.jpg" alt=""></p><p>搞定。從今往後，那個該死的解鎖密鑰環提示對話框再也不會來煩你了。</p><hr>`,23)),r("p",null,[t[1]||(t[1]=n("via: ",-1)),o(e,{href:"http://ask.xmodulo.com/disable-entering-password-unlock-default-keyring.html"},{default:s(()=>[...t[0]||(t[0]=[n("http://ask.xmodulo.com/disable-entering-password-unlock-default-keyring.html",-1)])]),_:1})]),r("p",null,[t[5]||(t[5]=n("作者：",-1)),o(e,{href:"http://ask.xmodulo.com/author/nanni"},{default:s(()=>[...t[2]||(t[2]=[n("Dan Nanni",-1)])]),_:1}),t[6]||(t[6]=n(" 譯者：",-1)),o(e,{href:"https://github.com/GOLinux"},{default:s(()=>[...t[3]||(t[3]=[n("GOLinux",-1)])]),_:1}),t[7]||(t[7]=n(" 校對：",-1)),o(e,{href:"https://github.com/wxy"},{default:s(()=>[...t[4]||(t[4]=[n("wxy",-1)])]),_:1})]),r("p",null,[t[10]||(t[10]=n("本文由 ",-1)),o(e,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[8]||(t[8]=[n("LCTT",-1)])]),_:1}),t[11]||(t[11]=n(" 原創翻譯，",-1)),o(e,{href:"https://linux.cn/"},{default:s(()=>[...t[9]||(t[9]=[n("Linux中國",-1)])]),_:1}),t[12]||(t[12]=n(" 榮譽推出",-1))])])}const L=a(d,[["render",m]]);export{w as __pageData,L as default};
